<script lang="ts">
  import { onMount, onDestroy } from 'svelte';
  import * as THREE from 'three';
  import { videoStore, type VideoRecording } from '$stores/video.svelte';
  let canvas: HTMLCanvasElement; let preview = $state<HTMLVideoElement>();
  let recorder: MediaRecorder | null = null; let stream: MediaStream | null = null; let microphoneStream: MediaStream | null = null; let audioContext: AudioContext | null = null; let chunks: Blob[] = []; let timer: ReturnType<typeof setInterval> | null = null; let startedAt = 0;
  let visualizer: THREE.WebGLRenderer | null = null; let animation = 0; let ribbons: THREE.Mesh[] = [];
  let isRecording = $state(false); let duration = $state(0); let includeAudio = $state(true); let includeMicrophone = $state(true); let previewVolume = $state(1); let error = $state(''); let selected = $state<VideoRecording | null>(null); let trimStart = $state(0); let trimEnd = $state(0); let playhead = $state(0); let projectName = $state('Study walkthrough'); let isExporting = $state(false);
  onMount(() => { buildScene(); const first = videoStore.items[0]; if (first) select(first); });
  onDestroy(() => { stopStream(); if (typeof window !== 'undefined') cancelAnimationFrame(animation); visualizer?.dispose(); });
  async function startCapture() {
    error = '';
    if (!navigator.mediaDevices?.getDisplayMedia || typeof MediaRecorder === 'undefined') { error = 'Screen recording is not available in this browser. Use a current version of Chrome, Edge, or Firefox over HTTPS.'; return; }
    try {
      const display = await navigator.mediaDevices.getDisplayMedia({ video: { frameRate: 30 }, audio: includeAudio });
      microphoneStream = null;
      if (includeMicrophone) {
        try { microphoneStream = await navigator.mediaDevices.getUserMedia({ audio: { echoCancellation: true, noiseSuppression: true, autoGainControl: true } }); }
        catch { error = 'Microphone access was not granted. Recording will continue with any tab/system sound you share.'; }
      }
      stream = await createCaptureStream(display, microphoneStream);
      const mime = ['video/webm;codecs=vp9,opus','video/webm;codecs=vp8,opus','video/webm'].find((type) => MediaRecorder.isTypeSupported(type));
      recorder = mime ? new MediaRecorder(stream, { mimeType: mime, videoBitsPerSecond: 4_000_000 }) : new MediaRecorder(stream);
      chunks = []; recorder.ondataavailable = (event) => { if (event.data.size) chunks.push(event.data); };
      recorder.onstop = async () => { const blob = new Blob(chunks, { type: recorder?.mimeType || 'video/webm' }); const saved = await videoStore.add(blob, duration, projectName.trim() || undefined); selected = saved; trimStart = 0; trimEnd = duration; isRecording = false; stopStream(); };
      stream.getVideoTracks()[0]?.addEventListener('ended', () => { if (recorder?.state === 'recording') stopCapture(); });
      recorder.start(1000); startedAt = Date.now(); duration = 0; isRecording = true; timer = setInterval(() => duration = Math.floor((Date.now() - startedAt) / 1000), 1000);
    } catch (err) { error = err instanceof Error ? err.message : 'Screen sharing could not start.'; stopStream(); }
  }
  function stopCapture() { if (recorder?.state === 'recording') recorder.stop(); if (timer) clearInterval(timer); timer = null; }
  async function createCaptureStream(display: MediaStream, microphone: MediaStream | null): Promise<MediaStream> {
    const output = new MediaStream(display.getVideoTracks());
    const sources = [display, microphone].filter((item): item is MediaStream => Boolean(item && item.getAudioTracks().length));
    if (sources.length === 1) { sources[0].getAudioTracks().forEach((track) => output.addTrack(track)); return output; }
    if (sources.length > 1) {
      audioContext = new AudioContext(); const destination = audioContext.createMediaStreamDestination();
      sources.forEach((source) => audioContext?.createMediaStreamSource(source).connect(destination));
      destination.stream.getAudioTracks().forEach((track) => output.addTrack(track));
    }
    return output;
  }
  function stopStream() { stream?.getTracks().forEach((track) => track.stop()); microphoneStream?.getTracks().forEach((track) => track.stop()); audioContext?.close(); stream = null; microphoneStream = null; audioContext = null; }
  function select(recording: VideoRecording) { selected = recording; trimStart = 0; trimEnd = recording.duration || 0; playhead = 0; }
  function time(seconds: number) { const m = Math.floor(seconds / 60); return `${m}:${Math.floor(seconds % 60).toString().padStart(2,'0')}`; }
  function onLoaded() { if (preview && selected) { const d = Number.isFinite(preview.duration) ? preview.duration : selected.duration; trimEnd = d; } }
  function onTime() { if (!preview) return; playhead = preview.currentTime; if (trimEnd && preview.currentTime >= trimEnd) { preview.pause(); preview.currentTime = trimStart; } }
  function seek(value: number) { if (preview) { preview.currentTime = value; playhead = value; } }
  function download() { if (!selected) return; const a = document.createElement('a'); a.href = selected.url; a.download = `${selected.name.replace(/[^a-z0-9]+/gi,'-').toLowerCase() || 'screen-recording'}.webm`; a.click(); }
  async function exportTrimmed() {
    if (!selected || !trimEnd || trimEnd - trimStart < .15) return;
    if (trimStart <= .05 && (!preview?.duration || trimEnd >= preview.duration - .05)) { download(); return; }
    const source = document.createElement('video') as HTMLVideoElement & { captureStream?: () => MediaStream };
    source.src = selected.url; source.playsInline = true; isExporting = true; error = '';
    try {
      await new Promise<void>((resolve, reject) => { source.onloadedmetadata = () => resolve(); source.onerror = () => reject(new Error('This clip could not be prepared for export.')); });
      source.currentTime = trimStart; await new Promise<void>((resolve) => { source.onseeked = () => resolve(); });
      const captured = source.captureStream?.();
      if (!captured) throw new Error('Trim export needs Chrome or Edge. Download the original WebM in this browser instead.');
      const type = ['video/webm;codecs=vp9,opus','video/webm;codecs=vp8,opus','video/webm'].find((item) => MediaRecorder.isTypeSupported(item));
      const exportRecorder = type ? new MediaRecorder(captured, { mimeType: type, videoBitsPerSecond: 4_000_000 }) : new MediaRecorder(captured);
      const pieces: Blob[] = [];
      const completed = new Promise<Blob>((resolve) => { exportRecorder.ondataavailable = (event) => { if (event.data.size) pieces.push(event.data); }; exportRecorder.onstop = () => resolve(new Blob(pieces, { type: exportRecorder.mimeType || 'video/webm' })); });
      source.ontimeupdate = () => { if (source.currentTime >= trimEnd) { source.pause(); if (exportRecorder.state !== 'inactive') exportRecorder.stop(); } };
      exportRecorder.start(); await source.play(); const result = await completed;
      const url = URL.createObjectURL(result); const link = document.createElement('a'); link.href = url; link.download = `${selected.name.replace(/[^a-z0-9]+/gi,'-').toLowerCase() || 'screen-recording'}-trimmed.webm`; link.click(); setTimeout(() => URL.revokeObjectURL(url), 1000);
    } catch (err) { error = err instanceof Error ? err.message : 'Trim export could not be completed.'; }
    finally { source.pause(); source.removeAttribute('src'); source.load(); isExporting = false; }
  }
  function buildScene() { const scene = new THREE.Scene(); const camera = new THREE.PerspectiveCamera(55, 1, .1, 100); camera.position.set(0, 0, 8); visualizer = new THREE.WebGLRenderer({ canvas, antialias:true, alpha:true }); visualizer.setPixelRatio(Math.min(devicePixelRatio, 2)); const light = new THREE.PointLight(0x60a5fa, 24, 20); light.position.set(0, 3, 4); scene.add(light, new THREE.AmbientLight(0x5b21b6, 1.1)); for(let i=0;i<15;i++){ const mesh = new THREE.Mesh(new THREE.TorusKnotGeometry(.26 + (i%3)*.08,.055,60,10),new THREE.MeshStandardMaterial({color:new THREE.Color().setHSL(.55+i/90,.75,.58),emissive:0x172554,metalness:.75,roughness:.25})); mesh.position.set((Math.random()-.5)*6,(Math.random()-.5)*3,(Math.random()-.5)*2); mesh.userData={speed:.002+i*.00013,offset:i}; scene.add(mesh); ribbons.push(mesh); } const resize=()=>{if(!visualizer)return;visualizer.setSize(canvas.clientWidth,canvas.clientHeight,false);camera.aspect=canvas.clientWidth/canvas.clientHeight;camera.updateProjectionMatrix()};addEventListener('resize',resize);resize();const loop=()=>{ribbons.forEach((mesh)=>{mesh.rotation.x+=mesh.userData.speed;mesh.rotation.y+=mesh.userData.speed*1.4;mesh.position.y+=Math.sin(performance.now()/1000+mesh.userData.offset)*.002});visualizer?.render(scene,camera);animation=requestAnimationFrame(loop)};loop(); }
</script>

<svelte:head><title>Screen Studio · Happy Study</title><meta name="description" content="Record your screen and prepare study walkthrough videos." /></svelte:head>

<div class="studio">
  <section class="studio-head"><canvas bind:this={canvas}></canvas><div><p class="eyebrow">SCREEN STUDIO</p><h1>Capture the lesson.<br /><em>Shape the story.</em></h1><p>Record a worked solution, coding session, presentation, or study walkthrough directly in your browser. Your clips are stored on this device.</p></div><div class="live-card"><span class:recording={isRecording}></span><small>{isRecording ? 'CAPTURING SCREEN' : 'READY'}</small><strong>{time(duration)}</strong></div></section>
  <section class="command-bar"><label>Project name<input bind:value={projectName} maxlength="80" /></label><label class="check"><input type="checkbox" bind:checked={includeAudio} /> Include shared-tab/system audio</label>{#if isRecording}<button class="stop" onclick={stopCapture}>■ Stop & save</button>{:else}<button class="capture" onclick={startCapture}>● New screen recording</button>{/if}</section>
  <section class="audio-options"><label><input type="checkbox" bind:checked={includeMicrophone} /> Include microphone narration</label><p>For tab/system sound, select a browser tab in the sharing picker and turn on its <strong>Share audio</strong> checkbox. Screen sound and your microphone are mixed into one video track.</p></section>
  {#if error}<p class="error">{error}</p>{/if}
  <div class="editor-shell"><aside class="media-bin"><div class="bin-title"><p class="eyebrow">MEDIA BIN</p><strong>Saved captures</strong></div>{#if !videoStore.items.length}<p class="empty">No clips yet. Record your screen to begin.</p>{:else}{#each videoStore.items as video, i}<button class:selected={selected?.id === video.id} onclick={() => select(video)}><span>{String(i+1).padStart(2,'0')}</span><div><strong>{video.name}</strong><small>{time(video.duration)} · {new Date(video.timestamp).toLocaleDateString()}</small></div></button>{/each}{/if}</aside>
  <main class="editor">{#if selected}<div class="preview"><video bind:this={preview} src={selected.url} onloadedmetadata={onLoaded} ontimeupdate={onTime} controls><track kind="captions" /></video></div><div class="timeline"><div class="timeline-top"><span>TRIM PREVIEW</span><span>{time(trimStart)} — {time(trimEnd)}</span></div><div class="track"><div class="clip" style={`left:${preview?.duration ? trimStart/preview.duration*100 : 0}%;right:${preview?.duration ? 100-trimEnd/preview.duration*100 : 0}%`}></div><input aria-label="Trim start" type="range" min="0" max={trimEnd || 0} step=".1" value={trimStart} oninput={(event) => { trimStart = Number((event.currentTarget as HTMLInputElement).value); if (trimStart > playhead) seek(trimStart); }} /><input aria-label="Trim end" type="range" min={trimStart} max={preview?.duration || trimEnd || 0} step=".1" value={trimEnd} oninput={(event) => trimEnd = Number((event.currentTarget as HTMLInputElement).value)} /></div><div class="scrubber"><span>{time(playhead)}</span><input aria-label="Playback position" type="range" min={trimStart} max={trimEnd || 0} step=".1" value={playhead} oninput={(event) => seek(Number((event.currentTarget as HTMLInputElement).value))} /><span>{time(trimEnd)}</span></div><p>Move the in/out points, preview the selection, then export a real trimmed WebM.</p></div><div class="editor-actions"><button onclick={download}>Download original</button><button disabled={isExporting} onclick={exportTrimmed}>{isExporting ? 'Exporting trim…' : 'Export trimmed WebM'}</button><button onclick={() => { const name = prompt('Rename clip', selected?.name); if (name?.trim() && selected) videoStore.rename(selected.id,name.trim()); }}>Rename</button><button class="danger" onclick={() => { if (selected && confirm('Delete this capture?')) { videoStore.remove(selected.id); selected = videoStore.items[0] || null; } }}>Delete capture</button></div>{:else}<div class="blank"><span>▣</span><h2>Your editing canvas is ready</h2><p>Make a screen recording to create your first study video.</p></div>{/if}</main></div>
  <section class="feature-strip"><div><b>Capture</b><span>Choose an entire screen, app window, or browser tab.</span></div><div><b>Review</b><span>Set an in/out point and replay only the section you need.</span></div><div><b>Keep</b><span>Downloads and stored clips stay under your control on this device.</span></div></section>
</div>

<style>
  .studio{display:grid;gap:1rem}.studio-head{min-height:280px;position:relative;overflow:hidden;border:1px solid rgba(96,165,250,.28);border-radius:22px;background:linear-gradient(110deg,#0f172a,#172554);display:flex;align-items:center;padding:clamp(1.5rem,5vw,4rem)}.studio-head canvas{position:absolute;inset:0;width:100%;height:100%;opacity:.76}.studio-head>div{position:relative;z-index:1;max-width:680px}.eyebrow{font-size:.66rem;letter-spacing:.14em;font-weight:850;color:#93c5fd;margin:0 0 .6rem}.studio-head h1{font-size:clamp(2.6rem,6vw,5rem);line-height:.9;letter-spacing:-.07em;margin:0}.studio-head h1 em{font-family:Georgia,serif;color:#93c5fd;font-weight:400}.studio-head p:not(.eyebrow){color:#cbd5e1;max-width:610px;line-height:1.65}.live-card{position:absolute!important;right:1.3rem;bottom:1.3rem;z-index:2!important;padding:1rem;background:rgba(2,6,23,.68);border:1px solid rgba(148,163,184,.2);border-radius:14px;display:grid;grid-template-columns:10px 1fr;column-gap:.5rem;align-items:center;min-width:160px}.live-card>span{grid-row:span 2;width:8px;aspect-ratio:1;border-radius:50%;background:#64748b}.live-card>span.recording{background:#fb7185;box-shadow:0 0 0 6px rgba(244,63,94,.18);animation:pulse 1s infinite}.live-card small{font-size:.64rem;letter-spacing:.1em;color:#94a3b8}.live-card strong{font:1.35rem ui-monospace,monospace}.command-bar{display:flex;gap:.7rem;align-items:end;flex-wrap:wrap;padding:1rem;border:1px solid rgba(148,163,184,.16);border-radius:14px;background:rgba(15,23,42,.8)}.command-bar label{display:grid;gap:.3rem;color:#94a3b8;font-size:.7rem;letter-spacing:.08em}.command-bar input[type=text],.command-bar input:not([type]){background:#070b18;border:1px solid #334155;border-radius:8px;color:#fff;padding:.58rem .7rem;width:250px}.command-bar .check{display:flex;align-items:center;gap:.45rem;padding:.6rem;color:#cbd5e1;letter-spacing:0}.command-bar button,.editor-actions button{border:1px solid rgba(148,163,184,.25);border-radius:8px;padding:.65rem .85rem;background:#172554;color:#e2e8f0;font-weight:750;cursor:pointer}.command-bar .capture{background:linear-gradient(135deg,#2563eb,#7c3aed);color:#fff}.command-bar .stop{background:#f43f5e;border-color:#f43f5e;color:#fff}.error{color:#fecdd3;background:rgba(190,24,93,.18);border:1px solid rgba(244,63,94,.35);padding:.75rem;border-radius:10px}.editor-shell{display:grid;grid-template-columns:260px 1fr;min-height:560px;border:1px solid rgba(148,163,184,.17);border-radius:18px;overflow:hidden;background:#0b1020}.media-bin{padding:.9rem;background:#0a0f1d;border-right:1px solid rgba(148,163,184,.15)}.bin-title{padding:.4rem .35rem 1rem}.bin-title strong{font-size:.9rem}.media-bin>button{width:100%;display:flex;gap:.65rem;text-align:left;padding:.7rem;border:1px solid transparent;background:transparent;border-radius:10px;color:#cbd5e1;cursor:pointer}.media-bin>button:hover,.media-bin>button.selected{background:rgba(37,99,235,.17);border-color:rgba(96,165,250,.32)}.media-bin>button>span{font-family:Georgia,serif;color:#93c5fd}.media-bin>button div{display:grid;gap:.15rem;min-width:0}.media-bin>button strong{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:.78rem}.media-bin>button small{font-size:.66rem;color:#64748b}.empty{color:#64748b;font-size:.8rem;padding:.4rem}.editor{display:flex;flex-direction:column;min-width:0}.preview{flex:1;min-height:330px;display:grid;place-content:center;padding:1rem;background:radial-gradient(circle,#172554,#060914)}.preview video{max-width:100%;max-height:430px;border-radius:8px;box-shadow:0 12px 36px rgba(0,0,0,.4)}.timeline{padding:1rem;border-top:1px solid rgba(148,163,184,.15);background:#0d1425}.timeline-top,.scrubber{display:flex;justify-content:space-between;align-items:center;color:#94a3b8;font-size:.7rem;letter-spacing:.08em}.track{height:42px;position:relative;margin:.7rem 0;background:repeating-linear-gradient(90deg,#1e293b 0 1px,transparent 1px 10%),linear-gradient(90deg,#172554,#0e7490);border-radius:7px;overflow:hidden}.clip{position:absolute;inset:0;background:rgba(14,165,233,.22);border-left:3px solid #67e8f9}.track input{position:absolute;inset:0;width:100%;opacity:0;cursor:ew-resize}.scrubber{gap:.7rem}.scrubber input{flex:1;accent-color:#60a5fa}.timeline p{font-size:.68rem;color:#64748b;margin:1rem 0 0}.editor-actions{display:flex;gap:.5rem;flex-wrap:wrap;padding:.8rem 1rem;border-top:1px solid rgba(148,163,184,.15)}.editor-actions button:first-child{background:#dbeafe;color:#172554}.editor-actions .danger{color:#fda4af;border-color:#fb7185}.blank{display:grid;place-content:center;justify-items:center;flex:1;text-align:center;color:#94a3b8}.blank span{font-size:3rem;color:#60a5fa}.blank h2{color:#e2e8f0;margin:.5rem}.feature-strip{display:grid;grid-template-columns:repeat(3,1fr);gap:1rem}.feature-strip div{display:grid;gap:.25rem;padding:1rem;border-radius:12px;background:rgba(30,41,59,.55);border:1px solid rgba(148,163,184,.14)}.feature-strip b{color:#bfdbfe}.feature-strip span{font-size:.8rem;color:#94a3b8}@keyframes pulse{50%{transform:scale(.8);opacity:.65}}@media(max-width:850px){.editor-shell{grid-template-columns:1fr}.media-bin{border-right:0;border-bottom:1px solid rgba(148,163,184,.15);display:flex;gap:.4rem;overflow:auto}.media-bin .bin-title{min-width:145px}.media-bin>button{min-width:185px}.feature-strip{grid-template-columns:1fr}.live-card{display:none}}@media(max-width:550px){.studio-head{min-height:340px;padding-top:7rem}.command-bar label{width:100%}.command-bar input[type=text],.command-bar input:not([type]){width:100%}.preview{min-height:250px}.editor-shell{min-height:500px}}
  .audio-options{display:flex;justify-content:space-between;align-items:center;gap:1rem;padding:.75rem 1rem;border-radius:12px;background:rgba(8,47,73,.38);border:1px solid rgba(34,211,238,.18)}
  .audio-options label{font-size:.84rem;color:#e0f2fe;font-weight:700;white-space:nowrap}
  .audio-options p{margin:0;color:#94a3b8;font-size:.76rem;line-height:1.4}.audio-options strong{color:#a5f3fc}
  .editor-actions button:disabled{opacity:.5;cursor:progress}
  @media(max-width:700px){.audio-options{align-items:flex-start;flex-direction:column;gap:.45rem}}
</style>
